sys_script.script:
/**
 * Business Rule: Auto Reject Conflicting Bookings
 * Table: Booking (x_2112820_sports_2_booking)
 * When: after / update
 * Conditions: Booking Status changes to Approved (booking_status == 'approved')
 * 
 * Objective:
 *   If multiple students submitted "Pending" requests for the same hall, date, and slot,
 *   as soon as the manager approves one request, this script automatically rejects all 
 *   other competing requests with a system note. This prevents double booking.
 */
(function executeRule(current, previous /*null when async*/) {
    // Query other bookings in 'pending' status for the exact same Sports Hall, Date, and Time Slot
    var conflictGr = new GlideRecord('x_2112820_sports_2_booking');
    conflictGr.addQuery('sys_id', '!=', current.getUniqueValue());
    conflictGr.addQuery('sports_hall', current.getValue('sports_hall'));
    conflictGr.addQuery('booking_date', current.getValue('booking_date'));
    conflictGr.addQuery('time_slot', current.getValue('time_slot'));
    conflictGr.addQuery('booking_status', 'pending');
    conflictGr.query();

    while (conflictGr.next()) {
        conflictGr.setValue('booking_status', 'rejected');
        var prevRemarks = conflictGr.getValue('remarks') || "";
        var appendMsg = "\n(System: Auto-rejected because booking request " + current.getValue('number') + " was approved first.)";
        conflictGr.setValue('remarks', prevRemarks + appendMsg);
        conflictGr.update();
    }
})(current, previous);
